import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import"./chunks/assets.BMT-GJtZ.js";var i=JSON.parse(`{"title":"Fields","description":"","frontmatter":{},"headers":[],"relativePath":"fields.md","filePath":"fields.md"}`),a={name:`fields.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h1><p>Fields are the building blocs of the module. They are the inputs that the user will fill in to customize the product.</p><p>Each field can have a name, a label and a type basically.</p><img src="/add-fields@2x.png" alt="Add fields" width="1774" height="1250"><p>The name allows the module to reference the field in the <a href="/formulas.html">formula</a>. The label is the text that will be displayed to the user. You can configure a label for each language of your shop.</p><p>The module supports many types of fields:</p><ul><li>Numeric Input</li><li>Slider</li><li>Dropdown</li><li>Radio buttons</li><li>Image list</li><li>Checkbox</li><li>Switch</li><li>Text</li><li>Text Area</li><li>Date</li><li>Image</li><li>File</li><li>Fixed Value</li><li>Price</li><li>Dynamic Variable</li><li>Feature</li><li>Divider</li><li>Color picker</li><li>Html</li><li>Error message</li><li>Custom field</li><li>Preview field</li><li>Country</li></ul><p>Each field type has its own settings. Some fields also have options such as the dropdown field or the radio buttons fields.</p><img src="/field-actions@2x.png" alt="Field actions" width="1898" height="524"><h2 id="field-settings" tabindex="-1">Field settings <a class="header-anchor" href="#field-settings" aria-label="Permalink to “Field settings”">​</a></h2><p>Here&#39;s how the field settings of a <code>Numeric</code> input look like:</p><img src="/field-settings@2x.png" alt="Field settings" width="958" height="1088"><h2 id="field-options" tabindex="-1">Field options <a class="header-anchor" href="#field-options" aria-label="Permalink to “Field options”">​</a></h2><p>Here&#39;s how the field options of a <code>Dropdown</code> field look like:</p><img src="/field-options@2x.png" alt="Field options" width="2024" height="736"><p>Each option can have a value and a secondary value.</p><p>When you reference the field in a formula, the field name will be replaced by the value of the selected option.</p><p>Example:</p><p>If the customer selects the <code>Wood</code> option in the <code>material</code> field above, and you have this price formula</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[material] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><p>then the formula will be evaluated as</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><p>Here&#39;s another example with a width and a height field:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[width] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [height] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [material]</span></span></code></pre></div><p>So the meter square cost will depend on the selected material.</p><p>You can also reference the secondary value of the selected option by using double brackets like this:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[material]] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><h2 id="error-message" tabindex="-1">Error message <a class="header-anchor" href="#error-message" aria-label="Permalink to “Error message”">​</a></h2><p>The <code>Error message</code> field displays a message to the customer.</p><p>While the error message is visible, the customer can&#39;t add the product to the cart. Hide it with a <a href="/conditions.html">condition</a> to allow add to cart again.</p><p>See <a href="/common-cases.html#display-a-custom-error-message">Display a custom error message</a> for an example.</p><h2 id="dynamic-variable" tabindex="-1">Dynamic variable <a class="header-anchor" href="#dynamic-variable" aria-label="Permalink to “Dynamic variable”">​</a></h2><p>The <code>Dynamic Variable</code> field holds a value that the module computes. The customer can&#39;t edit it. The product page shows its label and its current value as read-only text.</p><p>You can set its value with a <a href="/field-formulas.html">field formula</a> or with <a href="/php-calculation.html">PHP code</a>, then use it in your price formula like any other field.</p><p>See these examples:</p><ul><li><a href="/common-cases.html#charge-a-price-based-on-a-product-area">Charge a price based on a product area</a> (<code>area</code>)</li><li><a href="/common-cases.html#read-any-variable-from-prestashop">Read any variable from PrestaShop</a> (<code>customer_group</code>)</li><li><a href="/common-cases.html#invert-the-tax-calculation">Invert the tax calculation</a> (<code>tax_rate</code>)</li></ul>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};